package com.eventmgr.web;
import com.eventmgr.util.*;import javax.servlet.*;import javax.servlet.annotation.WebFilter;import javax.servlet.http.*;import java.io.*;import java.util.*;
@WebFilter("/api/*") public class AuthFilter implements Filter {public void doFilter(ServletRequest a,ServletResponse b,FilterChain c)throws IOException,ServletException{HttpServletRequest q=(HttpServletRequest)a;HttpServletResponse r=(HttpServletResponse)b;r.setHeader("Cache-Control","no-store");String p=q.getRequestURI().substring(q.getContextPath().length());if(!"GET".equals(q.getMethod())&&q.getHeader("X-Requested-With")==null){ApiServlet.error(r,403,"Missing X-Requested-With header");return;}if(p.startsWith("/api/auth")){c.doFilter(a,b);return;}HttpSession s=q.getSession(false);User u=s==null?null:(User)s.getAttribute("user");if(u==null){ApiServlet.error(r,401,"Please sign in");return;}Map<String,Object> row=Db.one("SELECT status FROM users WHERE id=?",u.id);if(row==null||!"ACTIVE".equals(row.get("status"))){s.invalidate();ApiServlet.error(r,401,"Account is inactive");return;}String role=p.startsWith("/api/admin")?"ADMIN":p.startsWith("/api/org")?"ORGANIZER":p.startsWith("/api/attendee")?"ATTENDEE":null;if(role==null&&!p.startsWith("/api/auth")){ApiServlet.error(r,404,"Not found");return;}if(role!=null&&!role.equals(u.role)){ApiServlet.error(r,403,"You do not have access to this area");return;}c.doFilter(a,b);}}
